mapper.select:
SELECT hbm.BP_CODE AS bp_code, t.prj_bp_id, t.project_id, t.bp_id, hbm.bp_name, hbm.bp_name AS bp_id_n, t.bp_type, t.description, T.BANK_ACCOUNT_ID, ( SELECT hba.BANK_ACCOUNT_NAME FROM hls_bp_master_bank_account hba WHERE hba.BANK_ACCOUNT_ID = T.BANK_ACCOUNT_ID ) BANK_ACCOUNT_ID_N, ( SELECT hba.BANK_ACCOUNT_NUM FROM hls_bp_master_bank_account hba WHERE hba.BANK_ACCOUNT_ID = T.BANK_ACCOUNT_ID ) BANK_ACCOUNT_NUM, ( SELECT hba.BANK_FULL_NAME FROM hls_bp_master_bank_account hba WHERE hba.BANK_ACCOUNT_ID = T.BANK_ACCOUNT_ID ) BANK_FULL_NAME, ( SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc.CODE = 'BP.BP_MASTER_ROLE' AND scv.VALUE = t.bp_type ) bp_type_n, hbm.bp_class, (select hbt.description from hls_business_type hbt where hbm.bp_class = hbt.business_type AND hbt.document_category = 'HLS_BP_MASTER') bp_class_n, hbm.economic_indu_classify, (select hsc.description from hls_stat_class hsc where to_char(hsc.class_id) = to_char(hbm.economic_indu_classify) and hsc.enabled_flag = 'Y') economic_indu_classify_n, hbm.GROUP_COMPANIES, t.credit_amount, HBM.industry, (select v.meaning from sys_code_value_b_v v where v.code = 'INDUSTRY_ORG' and v.code_value=HBM.industry) industry_n,hbm.credit_grade, ( SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc.CODE = 'RSC_CREDIT_RATING' AND scv.VALUE = to_char(hbm.credit_grade) ) credit_grade_n FROM prj_project_bp t, hls_bp_master hbm WHERE t.bp_id = hbm.BP_ID AND t.bp_type!= 'VENDER'
AND t.project_id=#{projectId}
AND t.bp_type in ('TENANT')

select ppb.PRJ_BP_ID,hli.lease_item_id,nvl(ppb.pledge_proportion,0) pledge_proportion from prj_project_bp ppb,hls_lease_item hli
 ppb.lease_item_id = hli.lease_item_id
    and ppb.project_id = ${projectId}

SELECT hbm.BP_CODE AS bp_code, t.prj_bp_id, t.project_id, t.bp_id, hbm.bp_name, hbm.bp_name AS bp_id_n, t.bp_type, t.description, T.BANK_ACCOUNT_ID, ( SELECT hba.BANK_ACCOUNT_NAME FROM hls_bp_master_bank_account hba WHERE hba.BANK_ACCOUNT_ID = T.BANK_ACCOUNT_ID ) BANK_ACCOUNT_ID_N, ( SELECT hba.BANK_ACCOUNT_NUM FROM hls_bp_master_bank_account hba WHERE hba.BANK_ACCOUNT_ID = T.BANK_ACCOUNT_ID ) BANK_ACCOUNT_NUM, ( SELECT hba.BANK_FULL_NAME FROM hls_bp_master_bank_account hba WHERE hba.BANK_ACCOUNT_ID = T.BANK_ACCOUNT_ID ) BANK_FULL_NAME, ( SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc.CODE = 'BP.BP_MASTER_ROLE' AND scv.VALUE = t.bp_type ) bp_type_n, hbm.bp_class, (select hbt.description from hls_business_type hbt where hbm.bp_class = hbt.business_type AND hbt.document_category = 'HLS_BP_MASTER') bp_class_n FROM prj_project_bp t, hls_bp_master hbm WHERE t.bp_id = hbm.BP_ID
AND t.project_id=#{projectId}
AND t.bp_type=#{bpType}

SELECT hbm.BP_CODE AS bp_code, t.prj_bp_id, t.project_id, t.bp_id, hbm.bp_name, hbm.bp_name AS bp_id_n, t.bp_type, t.description, T.BANK_ACCOUNT_ID, ( SELECT hba.BANK_ACCOUNT_NAME FROM hls_bp_master_bank_account hba WHERE hba.BANK_ACCOUNT_ID = T.BANK_ACCOUNT_ID ) BANK_ACCOUNT_ID_N, ( SELECT hba.BANK_ACCOUNT_NUM FROM hls_bp_master_bank_account hba WHERE hba.BANK_ACCOUNT_ID = T.BANK_ACCOUNT_ID ) BANK_ACCOUNT_NUM, ( SELECT hba.BANK_FULL_NAME FROM hls_bp_master_bank_account hba WHERE hba.BANK_ACCOUNT_ID = T.BANK_ACCOUNT_ID ) BANK_FULL_NAME, ( SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc.CODE = 'BP.BP_MASTER_ROLE' AND scv.VALUE = t.bp_type ) bp_type_n, hbm.bp_class, (select hbt.description from hls_business_type hbt where hbm.bp_class = hbt.business_type AND hbt.document_category = 'HLS_BP_MASTER') bp_class_n, hbm.economic_indu_classify, (select hsc.description from hls_stat_class hsc where hsc.class_id = hbm.economic_indu_classify and hsc.enabled_flag = 'Y') economic_indu_classify_n, hbm.GROUP_COMPANIES, t.credit_amount FROM prj_project_bp t, hls_bp_master hbm WHERE t.bp_id = hbm.BP_ID
AND t.project_id=#{projectId}
AND t.bp_type=#{bpType}

select ppb.prj_bp_id, ppb.project_id, ppb.bp_categroy, ppb.bp_type, (select hbm.description from hls_bp_type hbm where hbm.bp_type = ppb.bp_type) bp_type_n, ppb.is_credit_flag, ppb.description, (select hbm.bp_code from hls_bp_master hbm where hbm.bp_id = ppb.bp_id)bp_code, (select hbm.bp_code from hls_bp_master hbm where hbm.bp_id = ppb.bp_id)bp_code_n, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = ppb.bp_id)bp_name, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = ppb.bp_id)bp_name_n, ppb.communal_currency, (select fc.currency_name from fnd_currency fc where fc.currency_code = ppb.communal_currency)communal_currency_n, ppb.guarantee_amount, ppb.guarantee_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'FND_GUARANTEE_FORM' and s.code_value = ppb.guarantee_type)guarantee_type_n, ppb.np_guarantee_type, ppb.secured_party, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'NP.GUARANTEE_TYPE' and s.code_value = ppb.np_guarantee_type)np_guarantee_type_n, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'SECURED_PARTY' and s.code_value = ppb.secured_party)secured_party_n,
ppb.communal_other_currency, (select fc.currency_name from fnd_currency fc where fc.currency_code = ppb.communal_other_currency)communal_other_currency_n, ppb.communal_value, ppb.mortgage_evaluation_date, ppb.mortgage_evaluation_name, ppb.mortgage_evaluation_code, ppb.collateral_type, case when ppb.bp_type = 'MORTGAGOR' then (select s.MEANING from sys_code_value_b_v s where s.CODE = 'FND_MORTGAGE_CATEGORY' and s.code_value = ppb.collateral_type) else (select s.MEANING from sys_code_value_b_v s where s.CODE = 'FND_PLEDGE_CATEGORY' and s.code_value = ppb.collateral_type) end collateral_type_n, ppb.registration_authority, ppb.registration_date, ppb.mortgage_desc, ppb.collateral_code from prj_project_bp ppb where 1 = 1
and ppb.project_id = #{projectId}
and (ppb.bp_role_type not in ('WARRANTOR','MORTGAGOR','PLEDGOR') or ppb.bp_role_type is null)
and ppb.bp_type = #{bpType}
and ppb.bp_role_type = #{bpRoleType}
and (ppb.bp_role_type = 'MORTGAGOR' or ppb.bp_role_type = 'PLEDGOR')

select v.* from (SELECT hbm.bp_id, hbm.bp_code, hbm.bp_name, hbm.bp_class, (select hbt.description from hls_business_type hbt where hbm.bp_class = hbt.business_type AND hbt.document_category = 'HLS_BP_MASTER') bp_class_n, hbm.extra_nam, hbm.external_bp_code, hbm.enabled_flag, hbm.enterprise_scale, hbm.industry, hbm.legal_form, hbm.legal_representative, hbm.actual_controller, hbm.registered_place, hbm.registered_date, hbm.registered_capital, hbm.paid_in_capital, hbm.enterprise_unified_credit_code, hbm.founded_date, hbm.business_license_num, hbm.organization_code, hbm.tax_registry_num, hbm.loan_card_num, hbm.loan_card_password, hbm.taxpayer_type, hbm.invoice_title, hbm.invoice_bp_address_phone_num, hbm.invoice_bp_bank_account, hbm.nationality, hbm.date_of_birth, hbm.native_place, hbm.id_type, hbm.id_card_no, hbm.marital_status, hbm.academic_background, hbm.age, hbm.gender, hbm.annual_income, hbm.working_company, hbm.company_industry, hbm.business_job, hbm.working_years, hbm.phone, hbm.cell_phone, hbm.email, hbm.primaryiness, hbm.authority_rule_string, hbm.associated_division, hbm.three_certificates, hbm.operating_period_start, hbm.operating_period_end, hbm.environmental_level, hbm.group_customers, hbm.liabilities, hbm.situation_description, hbm.main_experience, hbm.family_name, hbm.family_gender, hbm.family_relationship, hbm.family_academic_background, hbm.family_id_type, hbm.family_id_card_no, hbm.family_date_of_birth, hbm.family_contact_information, hbm.family_contact_address, hbm.object_version_number, hbm.last_update_login, hbm.request_id, hbm.program_id, hbm.created_by, hbm.last_updated_by, hbm.creation_date, hbm.last_update_date, hbm.domestic_oversea, hbm.local_nonlocal, hbm.org_type, hbm.start_active_date, hbm.end_active_date, hbm.company_information, hbm.main_products, hbm.primary_business, hbm.bp_eng_name, hbm.agency_credit_code, hbm.bp_financial_type, hbm.registration_num_type, hbm.register_cert_num, hbm.account_license_num, hbm.register_capital_cur, hbm.economic_indu_classify, hbm.economic_indu_class_sec, hbm.economic_indu_class_thr, hbm.internal_indu, hbm.high_risk_indu, hbm.organization_type, hbm.organization_type_details, hbm.bp_classify, hbm.credit_line_amount, hbm.credit_type, hbm.credit_currency, hbm.valid_from, hbm.valid_to, hbm.company_id, hbm.bank_id, hbm.rele_com_flag, hbm.family_id_address, hbm.inter_status, hbm.inter_info, hbm.save_flag, hbm.data_class, hbm.change_req_id, hbm.bp_factor, hbm.bp_category, hbm.fin_note, hbm.owner_user_id, hbm.fin_org_type, hbm.enterprise_unified_creditcode, hbm.bank_code, hbm.bank_short_name, hbm.bp_title, hbm.number_of_children, hbm.period_in_job, hbm.place_of_birth, hbm.ref_v02, hbm.currency, hbm.exclusive_trade, hbm.customer_nature, hbm.enterprise_nature, hbm.economic_zone, hbm.business_classification, hbm.holding_type, hbm.listed_company, hbm.local_finance, hbm.exit_financing, hbm.customer_number, hbm.business_area, hbm.enterprise_affiliation, hbm.credit_customer, hbm.swift, TABALL.NAME, TABALL.UNIT_NAME, ppb.serial_number, ppb.prj_bp_id, ppb.bp_type, ppb.project_id, --ppb.bp_id, ppb.bp_role_type, ppb.description, ppb.bp_categroy, ppb.guarantee_type, ppb.guarantee_amount, ppb.communal_currency, ppb.np_guarantee_type, ppb.secured_party, ppb.communal_other_currency, ppb.communal_value, ppb.mortgage_evaluation_date, ppb.mortgage_evaluation_name, ppb.mortgage_evaluation_code, ppb.collateral_type, ppb.registration_authority, ppb.registration_date, ppb.mortgage_desc, ppb.collateral_code, ppb.ADDRESS_ID, ppb.CONTACT_INFO_ID, ppb.BANK_ACCOUNT_ID, ppb.IS_CREDIT_FLAG, /*(select save_flag from hls_bp_master where bp_id = ppb.bp_id) save_flag,*/ /*(select hbm.bp_class from hls_bp_master hbm where hbm.bp_id = ppb.bp_id) as bp_class,*/ /*(select hbm.phone from hls_bp_master hbm where hbm.bp_id = ppb.bp_id) as phone,*/ /*(select hbm.TAXPAYER_TYPE from hls_bp_master hbm where hbm.bp_id = ppb.bp_id) as taxpayer_type,*/ /*(select hbm.INVOICE_TITLE from hls_bp_master hbm where hbm.bp_id = ppb.bp_id) as invoice_title,*/ /*(select hbm.INVOICE_BP_ADDRESS_PHONE_NUM from hls_bp_master hbm where hbm.bp_id = ppb.bp_id) as invoice_bp_address_phone_num,*/ /*(select hbm.INVOICE_BP_BANK_ACCOUNT from hls_bp_master hbm where hbm.bp_id = ppb.bp_id) as invoice_bp_bank_account,*/ /*(select hbm.bp_code from hls_bp_master hbm where hbm.bp_id = ppb.bp_id) as bp_code,*/ /*(select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = ppb.bp_id) as bp_name,*/ (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = ppb.bp_id) as bp_id_n, (select hbm.bp_code from hls_bp_master hbm where hbm.bp_id = ppb.bp_id) as bp_code_n, (select hbt.description from hls_bp_type hbt where hbt.bp_type = ppb.bp_role_type) as prj_role, (select BANK_ACCOUNT_NUM from HLS_BP_MASTER_BANK_ACCOUNT t where t.BANK_ACCOUNT_ID = ppb.BANK_ACCOUNT_ID) bank_account_num, (select BANK_ACCOUNT_NAME from HLS_BP_MASTER_BANK_ACCOUNT t where t.BANK_ACCOUNT_ID = ppb.BANK_ACCOUNT_ID) bank_account_id_n, (select BANK_FULL_NAME from HLS_BP_MASTER_BANK_ACCOUNT t where t.BANK_ACCOUNT_ID = ppb.BANK_ACCOUNT_ID) bank_full_name, /*(SELECT hbm.LOAN_CARD_NUM FROM hls_bp_master hbm WHERE hbm.bp_id = ppb.bp_id) AS LOAN_CARD_NUM,*/ /*(SELECT hbm.ID_TYPE FROM hls_bp_master hbm WHERE hbm.bp_id = ppb.bp_id) AS ID_TYPE,*/ /*(SELECT hbm.ID_CARD_NO FROM hls_bp_master hbm WHERE hbm.bp_id = ppb.bp_id) AS ID_CARD_NO,*/ (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code_id = scvb.code_id and scvb.value = ppb.bp_role_type and scb.code = 'FCT.BP_TYPE') as bpRoleTypeDesc, (select t.COUNTRY || (select fp.description from fnd_province fp where fp.province = t.province) || (select fc.description from fnd_city fc where fc.city = t.city) || (select fd.description from fnd_district fd where fd.district = t.district) || t.ADDRESS from hls_bp_master_address t where t.address_id = ppb.address_id) address_id_n, (select c.contact_person || c.cell_phone from hls_bp_master_contact_info c where c.CONTACT_INFO_ID = ppb.CONTACT_INFO_ID) contact_info_id_n, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'PRJ.BP_TYPE' and scvb.value = ppb.bp_type) as bp_type_n, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'FCT.ACCOUNT_CURRENCY' and scvb.value = ppb.communal_currency) as communal_currency_desc, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'FND_GUARANTEE_FORM' and scvb.value = ppb.guarantee_type) as guarantee_type_desc, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'NP.GUARANTEE_TYPE' and scvb.value = ppb.np_guarantee_type) as np_guarantee_type_desc, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'SECURED_PARTY' and scvb.value = ppb.secured_party) as secured_party_desc, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'FCT.ACCOUNT_CURRENCY' and scvb.value = ppb.communal_other_currency) as communal_other_currency_desc, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'FND_MORTGAGE_CATEGORY' and scvb.value = ppb.collateral_type) as collateral_type_desc, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb, hls_bp_master hbm where hbm.bp_id = ppb.bp_id and scvb.code_id = scb.code_id and scb.code = 'FND.TAXPAYER_TYPE' and scvb.value = hbm.TAXPAYER_TYPE) as taxpayer_type_desc, -- row_number() over (partition by ppb.project_id,ppb.bp_type order by ppb.prj_bp_id) bp_seq IF ( @p = ppb.project_id and @q = ppb.bp_type , @rank := @rank + 1 ,@rank := 1 ) AS bp_seq, @p := ppb.project_id as rank1, @q := ppb.bp_type as rank2 from (SELECT @p := NULL ,@q := null,@rank := 0) r,prj_project_bp ppb left join hls_bp_master hbm on ppb.bp_id = hbm.bp_id left join (SELECT FE.NAME,SUA.USER_ID,MIN(FOU.UNIT_NAME) UNIT_NAME,SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID=FOU.UNIT_ID, (SELECT MIN(COMPANY_ID) COMPANY_ID,USER_ID FROM SYS_USER_ALLOCATION GROUP BY USER_ID ORDER BY USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID,SUA.COMPANY_ID,FE.NAME ORDER BY SUA.USER_ID ASC) TABALL on hbm.CREATED_BY = TABALL.USER_ID where nvl(ppb.bp_role_type,'CLIENT') not in ('PLEDGOR','MORTGAGOR') and ppb.bp_id is not null) v
1=1
and v.project_id = #{projectId}
and v.bp_type = #{bpType}
and v.bp_categroy = #{bpCategroy}
and v.bp_role_type = #{bpRoleType}
and v.bp_type not in ('WARRANTOR','MORTGAGOR','PLEDGOR')
and v.bp_code like concat('%',concat(#{bpCode},'%'))
and v.bp_name like concat('%',concat(#{bpName},'%'))
and v.bp_id = #{bpId}
and v.bp_type in ('TENANT','TENANT_SEC')
order by v.bp_seq

SELECT tab.* FROM( select ( select hbm.bp_class from hls_bp_master hbm where hbm.bp_id=ppb.bp_id )as bp_class, ( select hbm.phone from hls_bp_master hbm where hbm.bp_id=ppb.bp_id )as phone, ( select hbm.TAXPAYER_TYPE from hls_bp_master hbm where hbm.bp_id=ppb.bp_id )as TAXPAYER_TYPE, ( select hbm.INVOICE_TITLE from hls_bp_master hbm where hbm.bp_id=ppb.bp_id )as INVOICE_TITLE, ( select hbm.INVOICE_BP_ADDRESS_PHONE_NUM from hls_bp_master hbm where hbm.bp_id=ppb.bp_id )as INVOICE_BP_ADDRESS_PHONE_NUM, ( select hbm.INVOICE_BP_BANK_ACCOUNT from hls_bp_master hbm where hbm.bp_id=ppb.bp_id )as INVOICE_BP_BANK_ACCOUNT, ( select hbm.bp_code from hls_bp_master hbm where hbm.bp_id=ppb.bp_id )as bp_code, ( select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=ppb.bp_id )as bp_name, ( select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=ppb.bp_id )as bp_id_n, ( SELECT hbm.LOAN_CARD_NUM FROM hls_bp_master hbm WHERE hbm.bp_id = ppb.bp_id ) AS LOAN_CARD_NUM, ( SELECT hbm.ID_TYPE FROM hls_bp_master hbm WHERE hbm.bp_id = ppb.bp_id ) AS ID_TYPE, ( SELECT hbm.ID_CARD_NO FROM hls_bp_master hbm WHERE hbm.bp_id = ppb.bp_id ) AS ID_CARD_NO,
ppb.serial_number, ppb.contract_number, ppb.PRJ_BP_ID, ppb.project_id, ppb.chance_id, ppb.bp_id, ppb.description, ppb.bank_account_id, ppb.address_id, ppb.contact_info_id, ppb.COMMUNAL_CURRENCY, fc.currency_name communal_currency_n, fc2.currency_name communal_other_currency_n, ppb.COMMUNAL_OTHER_CURRENCY, ppb.COMMUNAL_VALUE, ppb.MORTGAGE_EVALUATION_DATE, ppb.MORTGAGE_EVALUATION_NAME, ppb.MORTGAGE_EVALUATION_CODE, ppb.COLLATERAL_TYPE, ppb.REGISTRATION_AUTHORITY, ppb.REGISTRATION_DATE, ppb.MORTGAGE_DESC, ppb.COLLATERAL_CODE, ppb.NP_GUARANTEE_TYPE, ppb.SECURED_PARTY, ppb.EXPIRY_DATE, ppb.bp_role_type, HBMBA.BANK_ACCOUNT_NUM, HBMBA.BANK_ACCOUNT_NAME, HBMBA.BANK_FULL_NAME, HBMBA.BANK_BRANCH_NAME, concat(concat(concat(concat(HBMA.country, ( SELECT t1.DESCRIPTION FROM FND_PROVINCE t1 WHERE t1.province = HBMA.province )), ( SELECT t1.DESCRIPTION FROM FND_CITY t1 WHERE t1.city = HBMA.city )), ( SELECT t1.DESCRIPTION FROM FND_DISTRICT t1 WHERE t1.district = HBMA.district)), HBMA.address) as address_id_n, concat(HBMCI.CONTACT_PERSON,HBMCI.CELL_PHONE) as contact_info_id_n, guarantee_amount, guarantee_type, v1.meaning guarantee_type_n, v2.meaning np_guarantee_type_n, v3.meaning secured_party_n, nvl(v4.meaning,'')||nvl(v5.meaning,'') collateral_type_n from prj_project_bp ppb left join Hls_Bp_Master_Bank_Account HBMBA on ppb.BANK_ACCOUNT_ID=HBMBA.BANK_ACCOUNT_ID left join hls_bp_master_address HBMA on HBMA.ADDRESS_ID=ppb.ADDRESS_ID left join hls_bp_master_contact_info HBMCI on HBMCI.CONTACT_INFO_ID=ppb.CONTACT_INFO_ID left join fnd_currency fc on fc.currency_code = ppb.COMMUNAL_CURRENCY left join fnd_currency fc2 on fc2.currency_code = ppb.COMMUNAL_OTHER_CURRENCY left join sys_code_value_b_v v1 on v1.code = 'FND_GUARANTEE_FORM' and v1.code_value = ppb.guarantee_type left join sys_code_value_b_v v2 on v2.code = 'NP.GUARANTEE_TYPE' and v2.code_value = ppb.NP_GUARANTEE_TYPE left join sys_code_value_b_v v3 on v3.code = 'SECURED_PARTY' and v3.code_value = ppb.SECURED_PARTY left join sys_code_value_b_v v4 on v4.code = 'FND_MORTGAGE_CATEGORY' and v4.code_value = ppb.COLLATERAL_TYPE left join sys_code_value_b_v v5 on v5.code = 'FND_PLEDGE_CATEGORY' and v5.code_value = ppb.COLLATERAL_TYPE ORDER BY ppb.CREATION_DATE ASC )tab
1 = 1
and tab.project_id=#{projectId}
and tab.chance_id=#{chanceId}
AND tab.bp_name like concat('%',concat(#{bpName},'%'))
AND tab.bp_role_type =#{bpRoleType}

mapper.delete:
delete from prj_project_bp ppb
1=1 and ppb.project_id = #{projectId} and ppb.bp_categroy = 'PRJ_PROJECT' and (ppb.bp_type = 'TENANT' or ppb.bp_type = 'TENANT_SEC' or ppb.bp_type = 'WARRANTOR') and ppb.prj_bp_id not in
#{prjBpIds}

mapper.select:
         select  ppb.*,m.bp_class  from prj_project_bp ppb,hls_bp_master  m where
	ppb.project_id = #{projectId}
and ppb.bp_type= #{bpType}
and ppb.BP_ID=m.BP_ID
and m.BP_CLASS= #{bpClass}

select ppb.prj_bp_id, ppb.chance_id, ppb.project_id, ppb.bp_categroy, ppb.bp_type, ppb.bp_id, ppb.guarantee_type, ppb.guarantee_amount, ppb.value_amount, ppb.pledge_rate, ppb.description, ppb.object_version_number, ppb.request_id, ppb.program_id, ppb.created_by, ppb.creation_date, ppb.last_updated_by, ppb.last_update_date, ppb.last_update_login, ppb.bank_account_id, ppb.address_id, ppb.contact_info_id, ppb.communal_currency, ppb.communal_other_currency, ppb.communal_value, ppb.mortgage_evaluation_date, ppb.mortgage_evaluation_name, ppb.mortgage_evaluation_code, ppb.collateral_type, ppb.registration_authority, ppb.registration_date, ppb.mortgage_desc, ppb.collateral_code, ppb.np_guarantee_type, ppb.contract_number, ppb.secured_party, ppb.contact_info, ppb.address_info, ppb.expiry_date, ppb.serial_number, ppb.bp_role_type, ppb.is_credit_flag, ppb.remarks from prj_project_bp ppb
1=1 and ppb.project_id = #{projectId} and ppb.bp_id = #{bpId} and ppb.bp_categroy = 'PRJ_PROJECT'
and ppb.bp_type = #{bpType}

select * from ( SELECT hmr.project_id, hmeb.bp_type, hls.bp_class, ( CASE WHEN hmeb.bp_type = 'WARRANTOR' THEN ( CASE WHEN hls.bp_class = 'ORG' THEN '法人担保人' WHEN hls.bp_class = 'NP' THEN '自然人担保人' END ) ELSE ( SELECT hbm.description FROM hls_bp_type hbm WHERE hbm.bp_type = hmeb.bp_type ) END ) bp_type_n, count( hmeb.prj_bp_id ) bp_count FROM prj_project hmr, prj_project_bp hmeb, hls_bp_master hls WHERE hmr.project_id = hmeb.project_id AND hmeb.bp_id = hls.bp_id AND hmeb.bp_type IN ('WARRANTOR') GROUP BY hmr.project_id, hmeb.bp_type, hls.bp_class UNION ALL SELECT hmr.project_id, hmeb.bp_type, '' AS bp_class, ( SELECT hbm.description FROM hls_bp_type hbm WHERE hbm.bp_type = hmeb.bp_type ) bp_type_n, count( hmeb.prj_bp_id ) bp_count FROM prj_project hmr, prj_project_bp hmeb, hls_bp_master hls WHERE hmr.project_id = hmeb.project_id AND hmeb.bp_id = hls.bp_id AND hmeb.bp_type IN ('TENANT_SEC') GROUP BY hmr.project_id, hmeb.bp_type ) v
1=1
and v.project_id = #{projectId}

select ppb.prj_bp_id, ppb.project_id, ppb.bp_id, ppb.bp_type, (SELECT bt.description FROM hls_bp_type bt WHERE ppb.bp_type = bt.bp_type) bp_type_n, ppb.bp_categroy, hbm.bp_name, hbm.bp_class, (select max(ma.country) from hls_bp_master_address ma where ma.bp_id = ppb.bp_id and ma.address_type = 'REGISTERED_ADDRESS') country, (select max(c.country_name) from hls_bp_master_address ma, fnd_country c where ma.bp_id = ppb.bp_id and ma.address_type = 'REGISTERED_ADDRESS' and c.country = ma.country) country_n, (select max(ma.province) from hls_bp_master_address ma where ma.bp_id = ppb.bp_id and ma.address_type = 'REGISTERED_ADDRESS') province, (select max(p.description) from hls_bp_master_address ma, fnd_province p where ma.bp_id = ppb.bp_id and ma.address_type = 'REGISTERED_ADDRESS' and p.province = ma.province) province_n, (select max(ma.city) from hls_bp_master_address ma where ma.bp_id = ppb.bp_id and ma.address_type = 'REGISTERED_ADDRESS') city, (select max(fc.description) from hls_bp_master_address ma, fnd_city fc where ma.bp_id = ppb.bp_id and ma.address_type = 'REGISTERED_ADDRESS' and fc.city = ma.city) city_n, hbm.economic_indu_classify, (select hsc.description from hls_stat_class hsc where hsc.class_id = hbm.economic_indu_classify and hsc.enabled_flag = 'Y') economic_indu_classify_n, hbm.strategic_bp_type, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'STRATEGIC_BP_TYPE' and sc.code_value = hbm.STRATEGIC_BP_TYPE) strategic_bp_type_n, (SELECT max(bcr.identification_result_o) FROM hls_bp_credit_rate bcr where bcr.bp_id = ppb.bp_id) identification_result_o, (SELECT max(sc.meaning) FROM hls_bp_credit_rate bcr, sys_code_value_b_v sc where bcr.bp_id = ppb.bp_id and sc.code = 'HLS.EXTERNAL_RATING_RESULT' and sc.code_value = bcr.IDENTIFICATION_RESULT_O) identification_result_o_n
from prj_project_bp ppb, hls_bp_master hbm ppb.bp_id = hbm.bp_id and ppb.bp_type in ('TENANT','TENANT_SEC','WARRANTOR')
and ppb.project_id = #{projectId}
